package dev.hrutvik.billing.credit;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import dev.hrutvik.billing.outbox.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.util.*;
@Service
public class CreditService {
 private final CreditStore store; private final OutboxEventRepository outbox; private final ObjectMapper json; private final Clock clock;
 public CreditService(CreditStore store,OutboxEventRepository outbox,ObjectMapper json){this(store,outbox,json,Clock.systemUTC());} CreditService(CreditStore s,OutboxEventRepository o,ObjectMapper j,Clock c){store=s;outbox=o;json=j;clock=c;}
 @Transactional public CreditResponse issue(String tenantId,UUID invoiceId,String idempotencyKey,CreditRequest request){String reason=request.reason().trim();String fingerprint=fingerprint(invoiceId,request.amount(),reason);var prior=store.find(tenantId,idempotencyKey);if(prior.isPresent()){if(!MessageDigest.isEqual(prior.get().fingerprint().getBytes(StandardCharsets.UTF_8),fingerprint.getBytes(StandardCharsets.UTF_8)))throw new CreditConflictException();return prior.get().response();}var balance=store.lockInvoice(tenantId,invoiceId);BigDecimal amount=request.amount().setScale(2,RoundingMode.HALF_UP);if(amount.signum()<=0)throw new IllegalArgumentException("credit rounds to zero at currency precision");if(amount.compareTo(balance.remaining())>0)throw new IllegalArgumentException("credit exceeds remaining invoice balance of "+balance.remaining());UUID id=UUID.randomUUID();String number="CR-"+id.toString().substring(0,8).toUpperCase(Locale.ROOT);Instant now=clock.instant();store.insert(id,number,tenantId,invoiceId,balance.currency(),amount,reason,idempotencyKey,fingerprint,now);try{outbox.save(new OutboxEvent(UUID.randomUUID(),id,"CREDIT_NOTE_ISSUED",tenantId,"billing.credit-note-issued.v1",json.writeValueAsString(Map.of("creditNoteId",id,"creditNumber",number,"invoiceId",invoiceId,"amount",amount,"currency",balance.currency())),now));}catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize credit event",e);}return new CreditResponse(id,number,invoiceId,balance.currency(),amount,reason,now,false);}
 private String fingerprint(UUID invoiceId,BigDecimal amount,String reason){String canonical=invoiceId+"|"+amount.stripTrailingZeros().toPlainString()+"|"+reason;try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(canonical.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
}
